        color = max(set(colors), key=colors.count)
        positions = [i for i, (r, c) in enumerate(coords) if grid[r][c] == color]
        if not positions or positions != list(range(min(positions), max(positions) + 1)):
            return None
        return color, min(positions), max(positions) + 1

    for horizontal in (True, False):
        bars = (edge_bar(horizontal, 0), edge_bar(horizontal, 1))
        if not all(bars) or bars[0][0] != bars[1][0]:
